import { test, expect } from '@playwright/test';

test.describe('Tab Navigation with URL Hash Update', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/tabs');
  });

  test('should update URL hash when switching tabs and display correct content', async ({ page }) => {
    // Verify initial state
    const tabList = page.getByRole('tablist');
    await expect(tabList).toBeVisible();
    const tab1 = page.getByRole('tab', { name: /tab 1/i });
    await expect(tab1).toBeVisible();
    const tab2 = page.getByRole('tab', { name: /tab 2/i });
    await expect(tab2).toBeVisible();

    // Click on tab 1
    await tab1.click();
    await expect(page).toHaveURL(/tabs\/#tab1/);
    const tab1Content = page.getByRole('region', { name: /tab 1 content/i });
    await expect(tab1Content).toBeVisible();

    // Click on tab 2
    await tab2.click();
    await expect(page).toHaveURL(/tabs\/#tab2/);
    const tab2Content = page.getByRole('region', { name: /tab 2 content/i });
    await expect(tab2Content).toBeVisible();

    // Verify content is displayed for tab 2
    const tab2Title = page.getByRole('heading', { name: /tab 2/i });
    await expect(tab2Title).toBeVisible();

    // Verify URL hash is correct
    const hash = page.evaluate(() => window.location.hash);
    expect(hash).toBe('/tabs/#tab2');
  });

  test('should handle back navigation and update URL hash accordingly', async ({ page }) => {
    // Navigate to tab 2
    const tab2 = page.getByRole('tab', { name: /tab 2/i });
    await tab2.click();
    await expect(page).toHaveURL(/tabs\/#tab2/);

    // Verify content is displayed for tab 2
    const tab2Content = page.getByRole('region', { name: /tab 2 content/i });
    await expect(tab2Content).toBeVisible();

    // Navigate back to tab 1 using browser back button
    await page.goBack();

    // Verify URL hash is updated to tab 1
    await expect(page).toHaveURL(/tabs\/#tab1/);

    // Verify content is displayed for tab 1
    const tab1Content = page.getByRole('region', { name: /tab 1 content/i });
    await expect(tab1Content).toBeVisible();

    // Verify tab 1 is active
    const tab1 = page.getByRole('tab', { name: /tab 1/i });
    await expect(tab1).toBeVisible();

    // Verify tab 2 is not visible
    const tab2 = page.getByRole('tab', { name: /tab 2/i });
    await expect(tab2).not.toBeVisible();
  });
});
